-- ============================================================================
-- developer/config/player_settings.lua
-- ============================================================================
-- SINGLE SOURCE OF TRUTH for all player configuration.
-- Edit this commented baseline directly when needed. Project > Game Settings... Save publishes
-- creator_settings.lua overrides and preserves this file.
--
-- DO NOT edit mvtk/player/player.script - those are internal defaults only.
-- All gameplay tuning should happen here.
-- ============================================================================
-- Generated by Project > Game Settings...

return {
  -- AFTER-HIT INVINCIBILITY (Game Settings > Combat > Invincibility).
  -- Seconds after the player is hurt during which further hits do no damage,
  -- lethal hits included. Damage over time, such as poison, keeps ticking.
  -- 0 turns it off. Player Size never changes it.
  damage_iframes = 0.8,
  -- LAUNCH CANNON: these hold settings do not change pad launches.
  launch = {
    cannon_invulnerable = true, -- Temporary damage immunity while loaded; lethal contacts still bypass it.
    cannon_animation = "crouch_idle", -- Existing visible player pose while held at the cannon centre.
    cannon_prompt = "{input:jump} Fire", -- DisplayText resolves this text and the player's remapped Jump button.
  },

  -- LANTERN (Game Settings > Advanced > Lantern); passive while unlocked.
  lantern = {
    ability_id = "lantern", -- Ability registry id granting the carried light.
    radius = 280, -- Unscaled world pixels, like torches; Player Size never changes it.
    intensity = 0.9, -- Light strength, 0..4; colour comes from lighting.lua light_color.
    flicker = 0.08, -- Fraction of intensity lost at the dimmest point, 0..1; 0 is steady.
    flicker_hz = 6, -- Flicker cycles per second; 0 holds the initial brightness.
    min_darkness = 0.2, -- Show the Lantern at or above this room/zone darkness, 0..0.9.
  },

  -- ZIP LINE (Game Settings > Advanced > Zip line).
  -- Ride speed and exit boost come from each Tiled Zip Line, in world px/s.
  zip_line = {
    hang_offset_px = 70, -- Player origin below the cable, in base px; always follows Player Size.
    release_on_jump = true, -- Jump lets go early; false keeps the player on the cable until its end.
    release_jump_speed = 900, -- Early-release upward base px/s; scales only with movement scaling.
    animation = "grapple", -- Player animation state used while riding; choose one your art provides.
  },

  -- FLOOR SURFACES (unitless, unscaled; Game Settings > Advanced > Ice).
  -- Painted ice and Ice Floor values of -1 inherit these presets. Only grounded
  -- acceleration/braking changes; air control is unchanged. Wall ice is separate
  -- in wall_surface_types.lua. Values 0..1: 1 means ordinary ground response.
  surfaces = {
    -- Default slippery floor material, independent of wall movement presets.
    ice = {
      accel_mult = 0.35, -- Ground acceleration multiplier (Game Settings: 0.01..1).
      decel_mult = 0.08, -- Ground stopping multiplier (0..1; smaller coasts longer).
      turn_brake_mult = 0.15, -- Ground reverse braking multiplier (0..1; smaller skids longer).
    },
  },
  -- SIZE
  -- The model's own files set its normal in-game size: 1.00 (100%) displays
  -- one image pixel as one world pixel. Player Size stretches the art for
  -- experiments; its unitless safe range is 1/7..8. After changing it, run
  -- "Prepare & Check" and Build to rebake sprite and collision resources.
  -- Pixel values below are world-size values at 1.00; the runtime multiplies
  -- body geometry and, when enabled below, movement by player_scale.
  player_scale = 1.00,
  -- Player/combat pixel-unit generation used for automatic override migration;
  -- unitless version, safe 1 or 2 (2 means the normal Player Size is 1.00).
  units_version = 2,
  -- When true (default), movement/kinematic pixel values (speeds, jump
  -- height, gravity, dash/glide/grapple values) also scale, preserving
  -- tile-relative game feel. When false, only body geometry scales.
  scale_movement = true,

  -- MOVEMENT
  walk_speed = 2100,
  run_speed = 3500,
  walk_speed_mode = "scaled",
  run_mode = "hold_button",
  run_threshold = 0.72,
  -- Dash uses the existing ground slide-to-run movement. Its ability unlock
  -- controls enabled at runtime; Slide must also be unlocked to start it.
  slide_to_run = {
    enabled = false,                 -- Starting unlock comes from ability_defaults.
    run_after_slide_when_held = true,-- Hold Slide through its finish to use run_speed.
    clear_run_on_release = true,     -- Releasing Slide returns to walking speed.
  },
  accel = 18, -- Speed build-up per second: higher reaches walking speed sooner, lower builds it gradually. Player Size does not scale it.
  -- How quickly a run reaches top speed once you reach walking speed. 0 uses Ground acceleration.
  run_accel = 0,
  decel = 26, -- Slowdown per second: higher stops sooner, lower coasts farther. Player Size does not scale it.
  -- Unitless turn factor: higher reverses sooner, lower skids longer. Player Size does not scale it.
  turn_brake_mult = 1,
  -- Horizontal recoil damping during hit-stun (per second). Lower values
  -- preserve more knockback; ordinary movement deceleration is independent.
  hurt_decel = 5,
  stop_epsilon = 5.25,
  -- Gameplay threshold for clearing the run gate near neutral. Controller
  -- hardware deadzone is configured once in game.project.
  walk_stop_deadzone = 0.20,
  air_accel_mult = 0.80,  -- Air control multiplier (1.0 = full control, 0.3 = floaty)
  -- Unitless air braking factor: higher sheds speed sooner, lower carries momentum longer. Player Size does not scale it.
  air_decel_mult = 1,

  -- WALK/RUN ANIMATION PACE (sprite and Spine)
  -- Playback follows horizontal movement relative to full walking speed.
  -- At walking speed the clip plays at 1x; running faster speeds up the legs.
  -- These settings affect animation only, never movement or camera speed.
  locomotion_animation = {
    enabled = true,        -- false restores each clip's authored playback speed.
    walk_multiplier = 0.8, -- Art tuning: raise if walking feet look too slow.
    run_multiplier = 5.0,  -- Lower if the run clip already has a faster stride.
    min_rate = 0.3,       -- Slowest playback while accelerating/decelerating.
    max_rate = 6.0,        -- Fastest playback, including movement speed boosts.
  },

  -- FOOTSTEP SOUND CADENCE
  -- Seconds between sound triggers at full  walk/run speed. Larger values
  -- mean slower footsteps. Slow analog walking spaces the sounds further
  -- apart; acceleration blends smoothly between walking and running cadence.
  -- This changes trigger timing, not the sound file's pitch or playback speed.
  footsteps = {
    enabled = true,        -- false silences movement-triggered footsteps.
    walk_interval = 0.24, -- Increase if walking still sounds too hurried.
    run_interval = 0.9,  -- Keeps the existing full-speed running cadence.
    min_speed_ratio = 0.02, -- Fraction of walk speed below which steps stop.
  },

  -- JUMPING
  gravity = -4200,
  jump_height = 448,
  extended_jump_height = 112,
  -- "gravity_scale" pulls harder while rising after release. "cut" sheds upward speed once on release.
  variable_jump_mode = "gravity_scale",
  jump_release_gravity_mult = 2.5, -- Stronger gravity mode: higher pulls down harder and makes short hops lower.
  jump_cut_speed_mult = 0.4, -- Cut speed mode: the share of upward speed kept on release. 0 ends the rise, 1 keeps all speed.
  -- How much higher a ground jump goes at full running speed. 0.2 is 20% higher. 0 turns the bonus off.
  speed_jump_bonus = 0,
  fall_gravity_mult = 1.5, -- Gravity factor during descent: higher makes the descent quicker, lower makes it floatier.
  jump_min_hold_time = 0.06, -- Seconds before releasing Jump can shorten it: higher raises the shortest hop, lower lets it end sooner.
  coyote_time = 0.12,
  jump_buffer = 0.12, -- Seconds a Jump press can wait for a landing: higher accepts earlier presses, lower needs closer timing.
  -- When a jump hits the corner of a ceiling with up to this many pixels of the body under it,
  -- the player slips sideways past it instead of stopping. Overlaps under about a tenth of the
  -- body's width already pass without it. The default is 24 px. 0 turns it off.
  -- In pixels at Player Size 1.00, and follows Player Size even when movement scaling is off.
  -- Very thin solids, a few pixels wide, are not guaranteed to block it.
  -- Not used with the Spine add-on's bone-driven collision.
  corner_correction_px = 24,
  -- Speed in px/s at Player Size 1.00. A higher value starts the hang farther from the top of the jump.
  -- A lower value narrows it, and 0 turns it off. Follows Player Size when movement scaling is enabled.
  -- An older apex_threshold_vy in this file still works when this is 0 and does not follow Player Size.
  apex_hang_speed = 0,
  -- Unitless gravity factor near the top of a jump: higher shortens the hang, lower lengthens it. Player Size does not scale it.
  -- Use at least 0.05. Zero can leave the player hanging indefinitely.
  apex_gravity_mult = 1,
  -- Gravity factor while holding Down during descent. Higher pulls down harder. Player Size does not scale it.
  fast_fall_mult = 1,
  -- Falling speed limit factor while holding Down during descent. 1 keeps the usual limit, 3 allows three times the speed.
  fast_fall_max_mult = 1,
  -- Falling cap in px/s at Player Size 1.00. Higher allows a faster fall up to the engine cap, lower slows it.
  -- 0 uses the engine cap alone. Follows Player Size when movement scaling is enabled.
  max_fall_speed_px = 0,
  air_jumps = 1,

  -- STATS
  max_health = 5,
  max_energy = 3,
  max_stamina = 100,

  -- COLLIDER
  collider_half_height = 59.9999575,
  collider_half_width = 46.45158,
  foot_floor_adjust = -15.48386,
  landing_snap_distance = 0,  -- Pixels above the floor where falling can auto-land. 0 disables the early ground snap.
  -- Ceiling collision tuning. head_margin is BASE px and scales with player_scale;
  -- collision_response.ceiling_response enables the terrain-contact safety net.
  head_margin = 27.096755,
  collision_response = {
    ceiling_response = true,
  },

  -- Spine bone names for the bundled BeardyBuck rig. Sprite mode ignores
