  spine_physics = {
    bone_map = {
      body = "waist",
      foot_l = "foot_far",
      foot_r = "foot_near",
      head = "head",
    },
  },

  -- ABILITIES
  -- Ladder exit height above the player root, as a multiple of collider half
  -- height. Tune to the raised hands in your climb art; 2 matches this sprite.
  -- Scales with the collider automatically. Up exits onto support over the
  -- ladder; Left/Right pulls onto support beside it once the hands reach it.
  ladder_climb = {
    hang_idle_animation = "hang", -- Movement animation while still on a hang bar; existing art by default.
    hang_move_animation = "hang", -- Movement animation while traversing a hang bar.
    mesh_animation = "", -- Blank keeps climb_up/down/idle; otherwise use this movement animation on meshes.
    hand_height_ratio = 2,
    -- Player origin below a hang bar's centre line, in base px; always follows
