    cooldown = 0.20,
    max_air_dashes = 1, -- Base charges restored on landing, before the upgrade.
    directions = "eight", -- "eight" follows the stick; "horizontal" keeps legacy X-only movement.
    allow_down = true, -- Allow down and down-diagonal directions in eight mode.
    diagonal_snap = true, -- Snap to 45 degrees; false uses the normalized stick angle.
    suspend_gravity = true, -- Hold the chosen vertical speed during an eight-mode dash.
    end_vertical_speed_mult = 0.35, -- Retain this fraction of vertical speed when eight mode ends.
    up_animation = "", -- Optional existing movement state (for example "jump"); empty uses the horizontal clip.
    down_animation = "", -- Optional existing movement state (for example "fall"); empty uses the horizontal clip.
    -- Used only when abilities.lua has no air_dash_iframes ability; normally
    -- the Dash Invincibility unlock decides.
    iframes = false,
  },

  -- Press Dash again during an air dash or a ground slide; no separate button.
  blink = {
    distance_px = 350, -- Maximum world-pixel distance at Player Size 1; scales with movement.
    min_distance_ratio = 0.25, -- Refuse destinations closer than this fraction of distance_px.
    search_steps = 12, -- Number of candidates from full distance down to the minimum, inclusive.
    allow_vertical = true, -- Allow upward, downward and diagonal teleports.
    diagonal_snap = true, -- Snap the stick to eight directions; false keeps its normalized angle.
    exit_vertical_speed = 0, -- Vertical speed in px/s after teleporting.
    keep_horizontal_speed = false, -- Retain pre-teleport horizontal speed when true; otherwise stop.
    iframes = 0.12, -- Seconds of ordinary damage immunity; lethal hits bypass it.
    cancel_grapple = true, -- Release the rope only after a successful teleport.
    fx_out = "dash", -- Effect from fx_types.lua at departure; empty disables it.
    fx_in = "dash", -- Effect from fx_types.lua at arrival; empty disables it.
    sound = "air_dash", -- Sound from sound config on success; empty disables it.
    chain_grace = 0.08, -- Seconds after a dash/slide ends that a second press still qualifies.
    from_air_dash = true, -- Allow the second press during or just after an air dash.
    from_ground_slide = true, -- Allow the second press during or just after a ground slide.
  },

  -- Passive Intangible Dash upgrade; uses the existing dash/slide input.
  intangible_dash = {
    enabled = false, -- PlayerHost replaces this with the Intangible Dash unlock.
    during_air_dash = true, -- Pass through Intangible Barriers during an air dash.
    during_slide = false, -- Also allow ground slides through these barriers when true.
    invulnerable = true, -- Lease ordinary damage immunity during passage; lethal hits bypass it.
  },

  -- Passive Extra Air Dash pickup: adds charges until the next landing.
  extra_air_dash = {
    bonus_dashes = 1, -- Charges added to max_air_dashes while the upgrade is unlocked.
  },

  wall_climb = {
    enabled = false,
    speed = 1050,
    climb_speed = 1050,
    -- 0 = stay put on the wall. Set > 0 (px/s) for slow descent while clinging.
    stick_speed = 0,
    contact_grace = 0.12,
    -- Wall jump without wall climb (wall slide). Only used when the player has
