  block_grab = {
    enabled = true,
    pull_speed = 1225,
    release_grace = 0.15,
  },

  -- High Jump is passive: the ability unlock controls this block immediately.
  high_jump = {
    enabled = false, -- Driven by the High Jump unlock, not a separate start choice.
    height_mult = 1.5, -- Multiplies ground jump height; unitless, so Player Size still applies.
    apply_to_air_jumps = false, -- Also raise air jumps when true; wall and grapple jumps stay normal.
  },

  -- Crawl-height body. Prepare & Check again after changing the height ratio.
  compact_form = {
    height_reduction_ratio = 0.45, -- Share of standing half-height removed from the top; capped at 0.9.
    move_speed_mult = 0.6, -- Crawl speed multiplier, 0.25..3; stacks with other temporary speed sources.
    roll_speed_mult = 1.0, -- Entry burst speed relative to walking speed.
    roll_time = 0.25, -- Seconds of entry burst before crawling; 0 skips the burst.
    roll_iframes = false, -- Optional burst invulnerability; lethal hits still bypass it.
    allow_jump = false, -- Allows a compact jump when a ceiling prevents standing.
    idle_animation = "crouch_idle", -- Idle clip while compact.
    move_animation = "crouch_walk", -- Crawling clip while compact.
    roll_animation = "roll", -- Entry burst clip.
  },

  -- Super Jump: hold Down while still on the ground, then press Jump.
  super_jump = {
    charge_time = 0.6, -- Seconds held before the charged launch is ready.
    down_threshold = 0.6, -- Downward input must exceed this strength (keyboard Down is 1).
    still_threshold = 0.25, -- Absolute horizontal input must stay below this strength.
    release_grace = 0.12, -- Seconds to retain charge after letting go of Down.
    launch_height_mult = 3.0, -- Unitless multiple of base jump height; does not stack with High Jump.
    lock_horizontal = true, -- Keep horizontal velocity zero until the rise ends.
    charge_animation = "crouch_idle", -- Existing pose while charging; customize for imported art.
    launch_animation = "jump", -- Existing airborne pose during the rise.
  },

  extended_jump = {
    enabled = false,
    hang_time = 0.15,
  },

  glide = {
    enabled = true,
    require_jump_held = true,
    gravity_mult = 0.22, -- Gravity factor when gliding. Higher gains falling speed faster, lower makes descent floatier.
    max_fall_speed = 1575, -- Falling cap in base px/s when gliding, scaled with movement. Higher permits a faster fall, lower slows it. 0 removes this cap.
  },

  -- Ground Pound: in the air, hold Down and press Heavy Attack (or the
